/* ---------------- distortion deck ---------------- */
const DISTORTION_TYPES = [
  { id: "catastrophizing", name: "Catastrophizing", short: "Assuming the worst possible outcome is the likely one." },
  { id: "mindreading", name: "Mind reading", short: "Being certain you know what others think — negatively." },
  { id: "fortune", name: "Fortune telling", short: "Predicting failure as if the future were fact." },
  { id: "allornothing", name: "All-or-nothing", short: "One flaw means total failure; no middle exists." },
  { id: "overgeneralization", name: "Overgeneralization", short: "One event becomes 'always' or 'never'." },
  { id: "personalization", name: "Personalization", short: "Taking blame for things you don't control." },
  { id: "shoulds", name: "Should statements", short: "Rigid rules that generate guilt and anger." },
  { id: "emotional", name: "Emotional reasoning", short: "'I feel it, therefore it's true.'" },
  { id: "labeling", name: "Labeling", short: "Turning one behavior into a permanent identity." },
  { id: "filter", name: "Mental filter", short: "Seeing only the negative detail in a full picture." },
  { id: "discounting", name: "Discounting the positive", short: "'That doesn't count' for anything good." },
];

