/* ---------------- character archetypes (verdict cards) ---------------- */
const ARCHETYPES = [
  { id: "fresh", emoji: "🐣", name: "Fresh Save File", line: "Character creation in progress. Everything is still possible.",
    when: (s, bp, cp) => (s.stats.assertiveChoices + s.stats.doormatChoices + s.stats.aggressiveChoices) < 5 },
  { id: "velvet-tank", emoji: "🥇", name: "The Velvet Tank", line: "Immovable object, impeccable manners. People say yes and feel good about it.",
    when: (s, bp, cp) => bp >= 75 && cp >= 60 && s.stats.assertiveChoices >= 10 },
  { id: "baron", emoji: "🗿", name: "The Boundary Baron", line: "Says no like it's a complete sentence. Because it is.",
    when: (s, bp) => bp >= 75 },
  { id: "flamethrower", emoji: "🔥", name: "The Flamethrower", line: "Right about everything, at maximum volume. We're working on the nozzle.",
    when: (s) => s.stats.aggressiveChoices >= 3 && s.stats.aggressiveChoices > s.stats.assertiveChoices },
  { id: "recovering", emoji: "🚪", name: "The Recovering Doormat", line: "The welcome mat is coming off the floor. Progress: visible.",
    when: (s) => s.stats.doormatChoices >= 3 && s.stats.doormatChoices > s.stats.assertiveChoices },
  { id: "unbothered", emoji: "🧊", name: "The Unbothered", line: "Anxiety calls. It goes to voicemail. Voicemail is full.",
    when: (s, bp, cp) => cp >= 70 },
  { id: "detective", emoji: "🕵️", name: "The Thought Detective", line: "Catches catastrophes at the border before they're granted a visa.",
    when: (s) => s.stats.distortionsCaught >= 10 },
  { id: "alchemist", emoji: "🧪", name: "The Perception Alchemist", line: "Sees the frame around every picture. Slightly dangerous at parties.",
    when: (s) => (s.stats.alchemyStrong || 0) >= 5 },
  { id: "diplomat", emoji: "🎭", name: "The Chaos Diplomat", line: "Walks into tension, leaves with allies. Nobody's sure how.",
    when: (s, bp) => bp >= 55 && s.stats.assertiveChoices >= 8 },
  { id: "wip", emoji: "🌱", name: "The Work In Progress", line: "Aren't we all. The reps are the point — keep swinging.",
    when: () => true },
];

