/* ---------------- campaign: Career Ladder ----------------
   Sequential rungs. Clear a rung by getting 2+ strong choices out of 3 rounds. */
const CAREER_STAGES = [
  { id: "interview", emoji: "🎤", title: "The Interview",
    desc: "Get in the door without shrinking yourself to fit through it.",
    scenarios: [
      { id: "cl-salary-q", tag: "Interview", focus: "E",
        text: "\"So — what are your salary expectations?\" The recruiter's pen hovers. You know the market range; you also really want this job.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "\"Oh, honestly whatever's standard is fine! I'm flexible. Really just excited to be here.\"",
            fb: "'Flexible' is the most expensive word in hiring — you just handed them a discount coupon before they even asked. Wanting the job and defending your number are not in conflict." },
          { kind: "avoid", backbone: 0, traits: { S: -1 },
            text: "\"Ha, good question! What's… the budgeted range for the role?\" (voice rising an octave, praying they blink first)",
            fb: "Asking their range is a legitimate tactic — but delivered as a dodge with a nervous laugh, it reads as fear, not strategy. Same words, steady voice, next time." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, S: 1, C: 1 },
            text: "\"Based on the market for this role and my launch record, I'm targeting 85–95k. Where does that sit against your range?\"",
            fb: "A researched range, anchored high, ending in a question that puts the ball back with them. This is exactly how the top of the band gets paid." },
          { kind: "assertDiplo", backbone: 1, traits: { E: 1, A: 1, S: 1 },
            text: "\"I'd love to hear the band you've budgeted — I'll say up front that similar roles are landing 85–95k for my experience, so I expect we'll overlap.\"",
            fb: "Courteous sequencing, same spine: you invited their number AND planted your anchor in the same breath. Nothing was surrendered." },
        ] },
      { id: "cl-weakness", tag: "Interview", focus: "S",
        text: "\"Tell me about your biggest weakness.\" The classic. The interviewer looks genuinely curious.",
        choices: [
          { kind: "avoid", backbone: 0, traits: { S: -1 },
            text: "\"I'd say I'm… too much of a perfectionist. I just care too much!\" (they visibly deflate)",
            fb: "The rehearsed humble-brag is a dodge everyone recognizes — it signals you won't be straight when a question gets uncomfortable. That's the actual data they collect." },
          { kind: "avoid", backbone: 0, traits: { S: -2 },
            text: "Freeze. Apologize. \"Sorry — mind blank! Sorry. Could we come back to it?\" Spend the next question replaying this one.",
            fb: "Blanking is human; the spiral afterward is the anxiety tax. A breath and 'let me think for a second' buys the same time without the apology or the rumination." },
          { kind: "good", backbone: 0, traits: { S: 2, C: 1 },
            text: "\"Delegating. On my last project I held tasks too long and became the bottleneck — so now I run a Friday handoff review. Last quarter, nothing sat with me over a week.\"",
            fb: "Real flaw, real fix, real number. Owning a genuine weakness calmly signals more stability than pretending you don't have one — which is the whole test." },
          { kind: "good", backbone: 0, traits: { S: 2, O: 1 },
            text: "Pause two seconds, then: \"Honest answer? Public pushback used to rattle me. I've been deliberately practicing — I now ask the challenger to make their case fully before I respond. It's changed my meetings.\"",
            fb: "The pause reads as thought, not panic — and describing yourself as someone who trains their weak spots is the most hireable trait there is." },
        ] },
      { id: "cl-lowball", tag: "Offer", focus: "A",
        text: "The offer lands: 12% below the bottom of the range you named — the range they nodded along to. \"We need an answer by Friday. The team's really excited about you!\"",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "Accept immediately. They might pull the offer if you push. 12% is only… a lot of money forever.",
            fb: "The first number becomes the base for every raise, bonus, and next-job anchor you'll ever get. Companies expect a counter — folding instantly just marks you as someone who folds." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "\"This is insulting. We discussed 85 minimum and you knew it. Is this how you treat people before they even start?\"",
            fb: "The gap is real; 'insulting' makes it personal. You want them defending the number, not defending themselves — indignation flips the wrong switch." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, S: 1 },
            text: "\"I'm excited too — and the base is below the 85–95 we discussed. At 88 I sign this week. Can you get there?\"",
            fb: "Enthusiasm and a firm counter in the same sentence — they are not opposites. A specific number with a deadline of your own turns their pressure play into a normal negotiation." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 1, E: 1, S: 1 },
            text: "\"Thank you — I want this to work. Help me understand the gap from the range we discussed? If base is truly capped, let's talk signing bonus or an early review with defined targets.\"",
            fb: "'Help me understand' makes them justify the lowball out loud (awkward for them, useful for you), and the alternatives give a cornered recruiter a face-saving path to yes." },
        ] },
    ] },
  { id: "newhire", emoji: "🌱", title: "New Hire",
    desc: "Survive the first 90 days without becoming the office's free labor.",
    scenarios: [
      { id: "cl-impostor", tag: "Week 2", focus: "S",
        text: "Week two. Everyone speaks in acronyms, your onboarding buddy is 'slammed,' and tonight's thought is: \"They're going to figure out they made a mistake hiring me.\"",
        choices: [
          { kind: "avoid", backbone: 0, traits: { S: -2 },
            text: "Hide the confusion. Nod in meetings, google frantically after, work till 9 to 'catch up' in secret.",
            fb: "The secrecy is the trap: it exhausts you AND blocks the questions that would actually close the gap. Impostor feelings fed with isolation grow." },
          { kind: "avoid", backbone: 0, traits: { S: -3 },
            text: "Rehearse the evidence nightly: the acronym you didn't know, the blank stare in standup. Verdict: fraud. Sentence: dread.",
            fb: "That's emotional reasoning plus a mental filter — cataloguing every stumble, discounting that they interviewed dozens and chose you. Feelings of fraudulence are a phase of learning, not a diagnosis." },
          { kind: "good", backbone: 0, traits: { S: 2, C: 1 },
            text: "Reality-check the math: every new hire is net-negative for months — that's priced in. Your job right now is question velocity, not output. Book 30 minutes with your buddy and bring a list.",
            fb: "Exactly: they didn't hire week-2 you, they hired month-12 you. Asking fast is the deliverable at this stage — the ones who struggle are the ones who hide." },
          { kind: "good", backbone: 0, traits: { S: 2, E: 1 },
            text: "Say it out loud at coffee: \"Week two and my brain is 60% acronyms — what did you all wish you'd asked in your first month?\"",
            fb: "Naming it casually converts private dread into a bonding ritual — every senior person at that table has a first-month horror story they're now delighted to tell you." },
        ] },
      { id: "cl-dumping", tag: "Month 2", focus: "A",
        text: "You said yes to everything your first month — and it worked: now three different people 'quickly loop you in' to their grunt work weekly. Your actual projects are slipping.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2, C: -1 },
            text: "Keep absorbing it. You're new — saying no is for people with tenure. Work weekends to protect your real projects.",
            fb: "You're teaching the office your yes is free, and the weekend work hides the cost so nothing ever corrects. The reputation you're building isn't 'reliable' — it's 'available'." },
          { kind: "aggressive", backbone: 0, traits: { A: -2 },
            text: "Reply-all to the next request: \"I'm not the team intern. Please route requests through my manager going forward.\"",
            fb: "The boundary is right; the flamethrower is not. Reply-all humiliation converts three mild over-askers into three enemies with long memories." },
          { kind: "assertDirect", backbone: 1, traits: { C: 2, S: 1 },
            text: "To each asker, warmly: \"I can't take this one — my launch is at risk. If it's urgent, flag it with Maya and she'll prioritize me.\" Then tell Maya the pattern.",
            fb: "A no with a legitimate routing beats a no with an apology. And surfacing the pattern to your manager reframes you from complainer to someone protecting the launch she cares about." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 1, C: 1, S: 1 },
            text: "\"Happy to help when I can — fair warning, I'm at capacity till the launch ships on the 15th. After that, bring me anything.\"",
            fb: "'After the 15th' converts a rejection into a raincheck — face fully saved, boundary fully intact, and you've defined when the door reopens instead of leaving it ajar." },
        ] },
      { id: "cl-first-meeting", tag: "Month 3", focus: "E",
        text: "Planning meeting, twelve people. You've spotted a real flaw in the proposed rollout — the same failure mode that burned your last company. You're the newest person in the room by years.",
        choices: [
          { kind: "avoid", backbone: -1, traits: { E: -2, S: -1 },
            text: "Say nothing. Who are you to correct the veterans? Watch the flaw ship three weeks later. Say nothing about that too.",
            fb: "The company paid for your outside experience and you left it in your bag. When the flaw ships, your silence retroactively becomes part of the failure." },
          { kind: "ok", backbone: 0, traits: { E: 1 },
            text: "Slack a teammate after: \"is it just me or does the rollout have the exact gap that killed our Q2 at my old place?\" Hope it travels upstream.",
            fb: "The observation was load-bearing; the delivery was deniable. Second-hand concerns arrive stripped of your evidence and your credit — say it where decisions happen." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, O: 1, S: 1 },
            text: "\"Before we lock this — I watched this exact sequencing fail at my last company. The gap is X. Can I take ten minutes after to show what fixed it?\"",
            fb: "Specific, evidence-based, and offered as a gift, not a veto. Speaking up with receipts in month three is how 'the new person' becomes 'the person we ask'." },
          { kind: "assertDiplo", backbone: 1, traits: { E: 1, A: 1, O: 1 },
            text: "\"Can I ask a naive-new-person question? What's our plan if X happens during rollout? I ask because I've seen it happen — happy to share the gory details.\"",
            fb: "The 'naive question' is a stiletto in a velvet glove: it surfaces the flaw, invites the room to find it 'themselves,' and threatens nobody. High-context cultures run on this move." },
        ] },
    ] },
  { id: "established", emoji: "🧱", title: "Establishing Yourself",
    desc: "Visibility, scope creep, and owning mistakes — the middle game.",
    scenarios: [
      { id: "cl-invisible", tag: "Visibility", focus: "E",
        text: "Performance review season. Your work is solid — but your manager's summary lists half of what you actually did. She genuinely doesn't seem to know the rest.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2, E: -1 },
            text: "Let it stand. Good work speaks for itself eventually. Probably. Someone will notice. Eventually.",
            fb: "Work is mute — you've seen this lesson before and it's truer with every level: managers report what they can see, and invisible work compounds into invisible careers." },
          { kind: "ok", backbone: 0, traits: { C: 1 },
            text: "Quietly start a 'brag document' for next cycle. This review is a loss; take it on the chin.",
            fb: "The brag doc is the right system — but conceding THIS review is six months of raise math you're donating. Fix the current record too; it takes one email." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, C: 1 },
            text: "\"Before this finalizes — the summary's missing the migration and the vendor save. Here's a one-pager with the numbers. Can we get these in?\"",
            fb: "Correcting your own record isn't bragging, it's data hygiene. A one-pager with numbers makes it effortless for her to say yes — effort transfer is the secret of upward management." },
          { kind: "assertDiplo", backbone: 1, traits: { E: 1, A: 1, C: 1 },
            text: "\"Could we make my update a monthly 3-bullet email? Reviews shouldn't be a memory test for you — and this cycle I'd add the migration and vendor save before it closes.\"",
            fb: "You fixed the review AND installed the system that prevents the problem forever, framed as making her life easier. That's establishing yourself, in one move." },
        ] },
      { id: "cl-scope-creep", tag: "Scope", focus: "C",
        text: "The project you own has quietly doubled: two 'small additions' from the VP, a 'while you're in there' from design. Same deadline. Everyone assumes it's all still on track.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2, C: -1 },
            text: "Absorb it. Nights and weekends can bend spacetime. Announce nothing; hope hard.",
            fb: "Silent absorption means when it slips, the record shows YOU missed a deadline — not that the project doubled. You're accepting the risk and donating the evidence." },
          { kind: "avoid", backbone: 0, traits: { S: -1 },
            text: "Mention it vaguely in standup — \"scope's gotten pretty big, heh\" — and interpret the silence as approval to keep drowning.",
            fb: "A vague flag nobody has to act on is not an escalation, it's an alibi. Decisions need a named owner, options, and a date — 'heh' has none of these." },
          { kind: "assertDirect", backbone: 1, traits: { C: 3, S: 1 },
            text: "Email the VP and your manager: \"Scope has grown 2x since kickoff (list attached). Same date is no longer real. Options: A) original scope on time, B) full scope +3 weeks, C) add a person. Which do you want?\"",
            fb: "The options email is the professional power move: it converts your private overload into their public decision, on the record, with no drama. This is what senior looks like." },
          { kind: "assertDiplo", backbone: 1, traits: { C: 2, A: 1 },
            text: "Book 15 minutes with the VP: \"I want to deliver what matters most to you. Everything on the list can't hit the same date — walk the list with me and rank it?\"",
            fb: "Ranking the list WITH the VP makes the trade-off theirs and flatters their judgment while your deadline quietly becomes realistic. Nothing was refused; everything changed." },
        ] },
      { id: "cl-own-mistake", tag: "Mistake", focus: "S",
        text: "Your config change just took the client dashboard down for 40 minutes. It's fixed now. Your stomach is a fist. Nobody has traced it to you — yet.",
        choices: [
          { kind: "avoid", backbone: 0, traits: { S: -3 },
            text: "Stay silent and refresh the incident channel for the rest of the day, rehearsing your defense. Maybe the logs are ambiguous.",
            fb: "Now you have two problems: the outage and the cover-up cortisol. Discovered honesty is worth half of volunteered honesty, and logs are never as ambiguous as you're hoping." },
          { kind: "doormat", backbone: 0, traits: { S: -2 },
            text: "Confess in a 400-word apology essay about your carelessness, offering to hand the project to someone more careful.",
            fb: "Flogging yourself in public forces everyone to spend the meeting reassuring you — you've converted your outage into their emotional labor. Accountability is calm, not theatrical." },
          { kind: "good", backbone: 0, traits: { S: 3, C: 1 },
            text: "Post in the channel now: \"Root cause was my config push at 14:02. Fixed at 14:41. Two changes so this can't recur: [X, Y]. Postmortem doc by Friday.\"",
            fb: "Own it, fix it, systematize it, in four sentences. Engineers get promoted off well-handled outages more often than off quiet quarters — composure under fire is the audition." },
          { kind: "good", backbone: 0, traits: { S: 2 },
            text: "Notice the catastrophe spiral ('fired by Friday'), run the evidence: 40 minutes, fixed, first incident all year. Then walk to your manager's desk and say it straight.",
            fb: "You caught the distortion before it wrote your script — the anxiety said career-ending, the data said Tuesday. Deciding from data while feeling the fear is the whole skill." },
        ] },
    ] },
  { id: "negotiation", emoji: "🎙️", title: "The Negotiation Table",
    desc: "Labels, mirrors, calibrated questions, and the power of silence.",
    scenarios: [
      { id: "cl-neg-frozen", tag: "The freeze", focus: "E",
        text: "You've made your raise case. Your manager sighs, sympathetic: \"I'd genuinely love to — but the budget's frozen this cycle. My hands are tied.\"",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2, E: -1 },
            text: "\"Oh — of course, totally understand. Maybe next year then! Thanks for hearing me out.\"",
            fb: "You accepted the first 'no' as the final answer, which no negotiator on earth does. 'Budget's frozen' is the opening position, not the ending — and you just closed the conversation for them, for free." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "\"That's what you said last cycle. Fine — I'll start taking recruiter calls and we'll see how frozen it is then.\"",
            fb: "The threat might even work once — and it converts your manager from potential ally into someone planning your replacement. Leverage announced as a weapon stops being leverage and starts being a countdown." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, S: 2 },
            text: "Slow, warm, unhurried: \"It sounds like your hands are tied on base pay this cycle.\" (Let that land.) \"So how can we get me to this number anyway — timing, title, scope, a dated commitment?\"",
            fb: "Two moves negotiation coach Chris Voss teaches: the label ('it sounds like…') makes them feel heard instead of fought, and the calibrated 'how' question hands them YOUR problem to solve. Note what you never said: 'okay'." },
          { kind: "assertDiplo", backbone: 1, traits: { E: 1, S: 2, A: 1 },
            text: "Lean back, echo the last words softly: \"…Frozen this cycle?\" Then stop talking. Completely.",
            fb: "The mirror — repeating their last few words and going quiet — is the highest-return, lowest-effort move in the Voss playbook: people can't resist filling the silence, and what they fill it with is usually the real constraint ('well, frozen for base — bonuses are separate…'). You just learned the map." },
        ] },
      { id: "cl-neg-silence", tag: "The pause", focus: "S",
        text: "Final interview. You said your number — 95k — clearly and calmly. The interviewer writes something down and says… nothing. Five full seconds of silence. Six. Seven.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -3 },
            text: "\"…but I'm super flexible on that! Totally open. It's really more of a ballpark, honestly.\"",
            fb: "You just negotiated against yourself — nobody in the room asked for a discount except you. Silence after a number is a tool, and it's aimed at exactly this reflex. The first person to speak pays." },
          { kind: "ok", backbone: 0, traits: { S: -1 },
            text: "Nervous laugh: \"Ha… is that crazy? That felt like a lot when I said it out loud.\"",
            fb: "You didn't cave, but the laugh handed over the frame: your own number, presented as a joke you're not sure of. A number delivered with apology is heard at 80% of face value." },
          { kind: "good", backbone: 1, traits: { S: 3 },
            text: "Hold the silence. Relaxed shoulders, easy breathing, comfortable eye contact. Let the seven seconds become ten. It's their turn.",
            fb: "The Charisma on Command principle: confidence isn't the words, it's the delivery — and nothing signals conviction like being visibly comfortable in a silence someone else built to pressure you. You said your number; the ball is theirs. Sit like you know that." },
          { kind: "good", backbone: 1, traits: { S: 2, E: 1 },
            text: "After a beat, calm and low, ending on a downward note: \"I'm confident that's the market for this scope. Happy to walk through how I got there.\"",
            fb: "Slow pace, downward inflection — Voss calls the register 'the late-night FM DJ voice' — plus an evidence offer. The tone does half the negotiating: statements that end like questions invite a haggle; statements that end like statements invite a yes." },
        ] },
      { id: "cl-neg-blocker", tag: "The blocker", focus: "A",
        text: "The head of operations has quietly killed your proposal in two review cycles. Everyone tells you he's immovable. You've booked 30 minutes with him tomorrow.",
        choices: [
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "Skip the meeting prep, go over his head instead: forward the proposal to the VP with a note about ops 'blocking innovation.'",
            fb: "Even if the VP sides with you, you've created a permanent enemy who owns half your dependencies. Winning a decision while losing the operator who implements it is how approved projects die quietly." },
          { kind: "avoid", backbone: -1, traits: { S: -1, O: -1 },
            text: "Pre-shrink the proposal before the meeting — strip out everything he might object to until what's left is inoffensive and, frankly, pointless.",
            fb: "Negotiating against yourself again, just in document form. You've conceded everything before hearing a single actual objection — and the shrunken version still might get killed, because the objection was never about the details." },
          { kind: "good", backbone: 1, traits: { A: 2, S: 2 },
            text: "Open with the accusation audit: \"You probably think this plan was cooked up by people who've never run a line, ignores your SLAs, and leaves your team holding the cleanup. Fair?\" Let him talk until he says \"…that's right.\" Then: \"So how do we fix it?\"",
            fb: "Voss's accusation audit — say their worst thoughts about you before they do — drains the fight from the room, and 'that's right' (not 'you're right,' which is what people say to end conversations) is the sound of a blocker becoming a co-author. People don't defend plans they helped fix." },
          { kind: "good", backbone: 1, traits: { A: 1, O: 1, S: 1 },
            text: "Aim for a small no instead of a big yes: \"Is it ridiculous to think we could pilot this on one line, your rules, without touching your SLAs?\"",
            fb: "'No'-oriented questions feel safe to answer — saying no keeps people in control, which is why 'is it ridiculous…' gets honest engagement where 'don't you agree…' gets resistance. A one-line pilot he governs is a no-risk yes wearing a no costume." },
        ] },
    ] },
  { id: "promotion", emoji: "📈", title: "The Promotion Push",
    desc: "Ask for the title, survive the politics, keep your health.",
    scenarios: [
      { id: "cl-ask-promo", tag: "The Ask", focus: "E",
        text: "You've been doing senior-level work for a year. A peer with less scope just got promoted. Your manager says you're 'crushing it' but the word 'promotion' has never come up.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2, E: -1 },
            text: "Keep crushing it harder. Surely the system notices eventually. Feel the resentment compound weekly like interest.",
            fb: "Your peer didn't out-perform you — they out-asked you. Promotions go disproportionately to people who state the goal out loud and make the checklist explicit." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "\"Jordan got promoted for THAT? I do twice the scope. What exactly is the bar here, favoritism?\"",
            fb: "Comparing yourself to Jordan makes it a grievance about him instead of a case about you — and 'favoritism' accuses your manager of corruption mid-negotiation. Case, not complaint." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, C: 1, S: 1 },
            text: "\"I want to be promoted to senior this cycle. Here's my doc mapping this year's work to every rubric line. What's missing — and if nothing, will you sponsor it?\"",
            fb: "Goal stated, evidence mapped, sponsorship requested — you've turned a vague hope into a project your manager now co-owns. 'What's missing' converts any no into a roadmap." },
          { kind: "assertDiplo", backbone: 1, traits: { E: 1, A: 1, C: 1 },
            text: "\"Where do you see me against the senior bar right now? I ask because I believe I'm there — and I'd like us to build the case together this cycle.\"",
            fb: "Opening with their assessment invites them to say it first (people defend conclusions they voiced), and 'build the case together' makes your promotion their win too." },
        ] },
      { id: "cl-rival", tag: "Politics", focus: "S",
        text: "A peer gunning for the same senior slot has started 'just asking questions' about your project in leadership channels — questions shaped like doubts. Today: \"curious if the timeline accounts for the issues we discussed?\" You discussed no issues.",
        choices: [
          { kind: "avoid", backbone: -1, traits: { S: -2 },
            text: "Ignore it. Engaging looks political, and you're above politics. Watch your project's reputation erode one 'innocent question' at a time.",
            fb: "Being above politics is a luxury only available to people whose work nobody is quietly redefining. Unanswered doubts become the record; silence ratifies them." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -2 },
            text: "Reply in-channel: \"What 'issues we discussed'? Name them. This is the second time you've invented concerns about my project and I think everyone can see why.\"",
            fb: "You just gave leadership a knife fight to watch. Even when you're right, the person who escalates publicly gets remembered as half of 'those two have a problem'." },
          { kind: "good", backbone: 1, traits: { S: 2, E: 1 },
            text: "Reply calmly with receipts: \"Timeline's green — tracker linked, risks logged with owners. Not sure which discussion you mean; happy to walk anyone through the plan.\" Then keep posting weekly status like clockwork.",
            fb: "Facts, links, zero heat — the insinuation dies in daylight and your composure IS the counter-argument. The weekly status makes the next 'question' land on a wall of receipts." },
          { kind: "good", backbone: 1, traits: { S: 2, A: 1 },
            text: "Handle the channel with one factual line, then DM: \"Twice now your questions have implied problems I don't recognize. If you have real concerns, bring them to me first — I'll always hear them. In leadership channels, bring evidence.\"",
            fb: "Public calm plus a private line in the sand: no audience for the confrontation, no ambiguity about the boundary. Most saboteurs fold instantly when named quietly." },
        ] },
      { id: "cl-burnout", tag: "Health", focus: "S",
        text: "Three weeks from the promotion decision. You're waking at 4am to check Slack, skipping workouts, snapping at home. A voice says: 'push through, rest after the title.'",
        choices: [
          { kind: "avoid", backbone: 0, traits: { S: -3, C: -1 },
            text: "Push through. Sleep is for the post-promotion era. Add a fourth coffee and a weekend 'catch-up' shift.",
            fb: "The 4am Slack checks aren't extra effort — they're the performance-degrading anxiety you're calling dedication. Burnout doesn't wait politely for the announcement." },
          { kind: "ok", backbone: 0, traits: { S: 0 },
            text: "Promise yourself a big vacation after the decision, and keep the current pace with the finish line as fuel.",
            fb: "The deferred-life plan assumes the finish line is real — but after the title comes the 'proving yourself in the new role' sprint. There's always a next line. The pattern is the problem." },
          { kind: "good", backbone: 0, traits: { S: 3, C: 1 },
            text: "Audit the actual rubric: the case is already submitted; 4am vigilance changes nothing now. Reinstate the workout, phone out of the bedroom, and let the decision be theirs while the health stays yours.",
            fb: "Separating what's in your control (the submitted case, your sleep) from what isn't (their decision) is stoicism with a calendar. Vigilance past the point of influence is just self-harm with a work ethic." },
          { kind: "good", backbone: 0, traits: { S: 2, A: 1 },
            text: "Tell your partner what's happening and ask them to call it when they see it: \"If I'm on Slack after 9, say the code word.\" Externalize the guardrail you can't hold alone right now.",
            fb: "Recruiting an outside enforcer for a boundary you keep breaking solo is not weakness — it's engineering. The people who last decades in careers all have one." },
        ] },
    ] },
  { id: "leading", emoji: "👑", title: "Leading People",
    desc: "The final rung: hard feedback, protecting your team, letting go.",
    scenarios: [
      { id: "cl-hard-feedback", tag: "Feedback", focus: "A",
        text: "Your best-liked report's last two deliverables were genuinely below the bar. Everyone likes them. The next project assignment is due, and the easy move is quietly routing the big one elsewhere.",
        choices: [
          { kind: "avoid", backbone: -1, traits: { A: -1, C: -1 },
            text: "Route the big project elsewhere without a word. Kinder than criticism, right? They'll never know. (They'll know.)",
            fb: "Silent demotion is the cruelest 'kindness' in management: they lose the growth, never learn why, and eventually hear it from the grapevine. Withheld feedback is stolen opportunity." },
          { kind: "doormat", backbone: -1, traits: { S: -1 },
            text: "Sandwich it into oblivion: ten compliments, one microscopic 'maybe tiny polish on details sometimes?', three more compliments. They leave beaming.",
            fb: "They left the meeting worse off than they entered — still not knowing. The feedback sandwich with 90% bread isn't kindness, it's your own comfort dressed as theirs." },
          { kind: "assertDirect", backbone: 1, traits: { A: 2, C: 1, S: 1 },
            text: "\"The last two deliverables were below your bar — specifically X and Y. That's unusual for you, so let's figure out what's going on. And I want you on the big project next; let's make sure the support's right.\"",
            fb: "Specific, curious, and paired with continued belief — that combination is what 'hard feedback from someone in your corner' feels like. Clear is kind; vague is cruel." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 2, S: 1 },
            text: "\"How do you feel the last two projects went?\" Listen fully. Then: \"Here's what I saw — X and Y slipped. What would make the next one land at your usual level?\"",
            fb: "Their self-assessment first: half the time they name the problem themselves, and owning a diagnosis beats receiving one. You supplied the missing specifics either way." },
        ] },
      { id: "cl-shield", tag: "Pressure", focus: "S",
        text: "The VP wants your team's deadline pulled in three weeks 'because the board deck says Q3.' Your team is already at a sustainable maximum. The VP is not famous for taking no well.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2, A: -1 },
            text: "\"We'll make it work.\" Walk out and tell the team the good news: mandatory crunch. You hate it too, so that makes it okay.",
            fb: "Passing pressure downward unfiltered isn't loyalty to the company — it's using your team's weekends to buy your own comfort with the VP. They'll remember who didn't fight." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "\"That's impossible and honestly this is why we keep losing engineers. The board deck is not my team's problem.\"",
            fb: "Even correct, 'not my problem' to a VP is a resignation letter with extra steps. The team needs you effective in that room, not righteous and radioactive." },
          { kind: "assertDirect", backbone: 1, traits: { S: 2, C: 2 },
            text: "\"Three weeks earlier means cutting the reporting module or adding two engineers — here's the math. Which trade do you want me to make? 'Same scope, same team, minus three weeks' isn't on the menu.\"",
            fb: "Leaders don't say no to VPs — they price the request. The math sheet moves the fight from your team's stamina to the VP's own trade-offs, which is where it belongs." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 1, S: 1, C: 1 },
            text: "\"Let's get the board what it needs — what does the deck actually require by Q3? Often it's the headline feature, not the whole release. I can land THAT three weeks early.\"",
            fb: "Interrogating the real requirement often shrinks it 80% — the board needs a demo, not the reporting module. You protected the team by solving the VP's actual problem." },
        ] },
      { id: "cl-delegate", tag: "Letting go", focus: "C",
        text: "The flagship client demo is Friday. Your report's draft is at 80% of how you'd do it. Every cell in your body wants to 'just fix it tonight' — like you always used to.",
        choices: [
          { kind: "avoid", backbone: 0, traits: { C: -1, S: -1 },
            text: "Rewrite it all at midnight, present their name on it, feel simultaneously heroic and resentful. Repeat forever.",
            fb: "The midnight rewrite steals their growth, hides the gap from them, and books you as the permanent bottleneck. Hero-ing is how leaders stay individual contributors with extra meetings." },
          { kind: "ok", backbone: 0, traits: { C: 1 },
            text: "Send back eleven tracked changes and a 'small tweaks!' note at 10pm, then hover over their shoulder tomorrow.",
            fb: "Eleven tracked changes IS the rewrite, just outsourced back with anxiety attached. They learn your preferences, not the principles — and the hovering says you don't trust them." },
          { kind: "good", backbone: 0, traits: { C: 2, A: 1, S: 1 },
            text: "30 minutes together: \"It's strong. Two things would make it land with THIS client — the cost slide up front, and cut section 3. Here's why.\" Then let their version, improved by them, ship.",
            fb: "Principles over edits: they now know WHY, which upgrades every future draft, not just this one. 80% theirs that becomes 95% theirs beats 100% yours forever." },
          { kind: "good", backbone: 0, traits: { C: 2, S: 2 },
            text: "Ask yourself the leader's question first: is this 80% actually below the client bar, or just below MY-style bar? If it clears the client bar — say so, and ship it untouched.",
            fb: "Half of 'quality concerns' at handoff are taste wearing quality's clothes. Distinguishing the two is the final boss of delegation — and the answer 'ship it' builds a team that doesn't need you at midnight." },
        ] },
    ] },
];

/* ---------------- campaign: Relationships ---------------- */
const LOVE_CHAPTERS = [
  { id: "first-dates", emoji: "☕", title: "First Dates",
    desc: "Show up as yourself — the one thing swiping can't do for you.",
    scenarios: [
      { id: "rl-post-date", tag: "After the date", focus: "S",
        text: "Great first date — you think? It's been 26 hours and no text. Your thumb hovers. Your brain offers: 'they're ghosting, the laugh was pity, you talked too much about the aquarium.'",
        choices: [
          { kind: "avoid", backbone: 0, traits: { S: -3 },
            text: "Reread the entire chat history for tone errors. Draft four openers. Send none. Check their profile activity hourly.",
            fb: "Monitoring mode: maximum anxiety, zero information, and the aquarium comment gets convicted on no evidence. 26 hours is a busy Tuesday, not a verdict." },
          { kind: "avoid", backbone: -1, traits: { S: -2, E: -1 },
            text: "Preemptively withdraw: 'they're clearly not interested, better to feel nothing now than rejected later.' Archive the chat.",
            fb: "Rejecting yourself first so they can't do it — the oldest anxiety bargain there is. You traded a possible relationship for a guaranteed nothing, and called it protection." },
          { kind: "good", backbone: 1, traits: { S: 2, E: 1 },
            text: "You had fun — so say so: \"Really enjoyed that. The place with the weird lamps you mentioned — take me Thursday?\" Send it once, then put the phone down and go live your day.",
            fb: "Interest stated plainly, a concrete plan proposed, and then — crucially — detachment from the outcome. Whatever they reply, you behaved like someone who knows what they want." },
          { kind: "good", backbone: 0, traits: { S: 3 },
            text: "Run the boring-explanations drill: work crunch, drafting their own text, playing it cool. Notice 'pity laugh' requires a conspiracy; 'busy Tuesday' requires nothing. Give it a day.",
            fb: "The likeliest explanation is almost always the dullest one — anxiety just files the dramatic version first. You audited the file. That's the skill." },
        ] },
      { id: "rl-late-date", tag: "The test", focus: "A",
        text: "Second date. They text 'running 10 late!!' — and arrive at minute 40, phone in hand, mid-story about their chaotic friend, no real apology.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "\"No worries at all!! I literally just got here!\" (You did not. You've read the menu eleven times.)",
            fb: "First dates are training data — you just taught them your time costs nothing and your stated feelings are decorative. Patterns set in week two are iron by year two." },
          { kind: "aggressive", backbone: 0, traits: { A: -2 },
            text: "\"Forty minutes. FORTY. This is honestly the most disrespectful start to a date I've ever had.\"",
            fb: "The grievance is legitimate; the artillery is not calibrated to a second date. You'll never learn if this was a fluke or a pattern, because there won't be a third data point." },
          { kind: "assertDirect", backbone: 1, traits: { S: 1, A: 1 },
            text: "Warm but level: \"Glad you made it. For the record, 40 minutes is a lot — a heads-up with the real ETA next time and we're square. Now — drinks?\"",
            fb: "Named once, standard set, evening rescued — no sulk, no sermon. How they respond to this exact sentence tells you more about them than the next three dates will." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 1, S: 1 },
            text: "Grin: \"You're lucky this menu is fascinating. I'll forgive the 40 minutes exactly once — future-you should know I rate punctuality slightly above flowers.\"",
            fb: "The boundary arrived wearing humor, but it arrived: they now know it registered, it matters, and repetition has a price. Charm and spine in the same sentence." },
        ] },
      { id: "rl-authentic", tag: "Being real", focus: "O",
        text: "Date three. They're describing weekend plans: trail running, a climbing gym, 'you climb, right?' You do not climb. You mentioned 'being outdoorsy' on date one because it felt like the right answer.",
        choices: [
          { kind: "avoid", backbone: -1, traits: { S: -2, O: -1 },
            text: "\"Totally! Love climbing.\" Buy chalk. Watch YouTube tutorials in a panic. Become, at enormous cost, a fictional person.",
            fb: "Every performed interest is a mortgage the real you has to service forever. The relationship you're protecting with the lie is with someone who hasn't met you yet." },
          { kind: "ok", backbone: 0, traits: { S: -1 },
            text: "Deflect vaguely — \"been a while, haha, work's been crazy\" — and steer to a safer topic before follow-up questions land.",
            fb: "The dodge survives today and reschedules the reckoning. Vagueness isn't honesty's budget version — it's just the lie with better lawyers." },
          { kind: "good", backbone: 1, traits: { O: 2, S: 2 },
            text: "Laugh: \"Confession — I said outdoorsy on date one because it sounded good. Truth: I hike occasionally and I've never climbed anything taller than a bouldering wall at a birthday party. Teach me?\"",
            fb: "The confession is charming precisely because it's brave, and 'teach me' converts the gap into a date. Compatibility can only be tested by the person you actually are." },
          { kind: "good", backbone: 0, traits: { O: 2, E: 1 },
            text: "\"Real answer: climbing's never grabbed me. My version of that thrill is [your actual thing]. Trade you — one climbing session for one of mine?\"",
            fb: "You declined the identity without declining the person, and proposed an exchange where both real selves show up. That's what date three is actually for." },
        ] },
    ] },
  { id: "friendship", emoji: "🫂", title: "Friendship",
    desc: "Making and keeping friends as an adult — same spine, platonic edition.",
    scenarios: [
      { id: "rl-make-friend", tag: "Making friends", focus: "E",
        text: "Six weeks into your pottery class, you and the person at the next wheel have a running joke and genuinely good chats. The course ends Thursday. Adults famously never make new friends after this exact moment.",
        choices: [
          { kind: "avoid", backbone: 0, traits: { E: -2, S: -1 },
            text: "Say \"see you around!\" on Thursday, mean it warmly, and never see them again. Add them to the pile of almost-friends the class system keeps producing.",
            fb: "Adult friendship dies exactly here — not from rejection but from nobody moving first. Proximity made this easy for six weeks; from Thursday, it costs one sentence of initiative, and the price only goes up." },
          { kind: "ok", backbone: 0, traits: { E: 1 },
            text: "\"We should totally hang out sometime!\" Exchange numbers. Both of you like this plan. Neither of you will ever activate it.",
            fb: "'Sometime' is where plans go to be fondly remembered instead of happening. You did the brave 80% and skipped the 20% that matters: a day, a time, a place." },
          { kind: "good", backbone: 1, traits: { E: 3, S: 1 },
            text: "\"Okay, real question — I'm doing the Saturday market run this weekend and you clearly have opinions about coffee. Come with? 10am, I'll send the spot.\"",
            fb: "Concrete beats cool: a specific invitation with a time signals 'I actually want this,' which is precisely the small vulnerability adult friendship requires. Worst case is a no that costs you nothing you weren't already about to lose Thursday." },
          { kind: "good", backbone: 0, traits: { E: 2, C: 1 },
            text: "Propose the recurring version: \"A few of us are doing the intermediate class next term — join, and let's make the after-class taco thing official.\"",
            fb: "Friendship research is unromantic: it's mostly repeated unplanned contact. A standing structure — same class, same tacos — manufactures the repetition that one-off coffee dates can't, which is why club friendships outlive coffee-date acquaintances." },
        ] },
      { id: "rl-one-sided", tag: "The ledger", focus: "A",
        text: "Scroll your texts with your oldest friend: the last eleven plans were initiated by you. The last three times you didn't reach out, months of silence followed. You're tired — and you miss them.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "Keep being the one who texts. Someone has to, and apparently it's you, forever. Swallow the growing resentment; it pairs well with the memories.",
            fb: "Carrying a friendship alone works right up until the resentment curdles the very thing you're carrying. Eleven-to-zero isn't a friendship pattern you're observing — it's one you're funding." },
          { kind: "aggressive", backbone: 0, traits: { A: -2 },
            text: "Test them with silence — months of it — then, when they finally text 'hey stranger!', reply with the full itemized invoice of every plan you ever initiated.",
            fb: "The silent test punishes them for failing an exam they didn't know they were taking, and the invoice turns a repairable imbalance into a trial. If the friendship matters, say the quiet part while it's still warm." },
          { kind: "assertDirect", backbone: 1, traits: { A: 2, S: 1 },
            text: "Say it without the prosecutor: \"I've noticed I do most of the reaching out, and it's started to sting. I'd rather tell you than quietly drift. What's going on on your end?\"",
            fb: "Pattern named, feeling owned, genuine question asked — and 'what's going on on your end' leaves room for the answer to be depression, chaos, or ADHD rather than indifference. Half the time it is. Now you're solving it together instead of auditing alone." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 1, S: 1, C: 1 },
            text: "Change the game instead of the scorecard: \"I want us to stop depending on whoever texts first — first Thursday of every month, same ramen place, standing order. In or out?\"",
            fb: "The standing date removes the initiative tax entirely — nobody has to be the one who reaches out, because the calendar does it. Many lopsided friendships aren't lopsided in caring, just in executive function; structure fixes what scorekeeping can't." },
        ] },
      { id: "rl-crisis-friend", tag: "The 2am calls", focus: "S",
        text: "Your friend is going through a brutal breakup. You've been there for them — truly. But it's now the fourth 2am call this week, you have work at 8, and you can feel your own battery at 4%.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -3 },
            text: "Answer every call at any hour. Being tired is a small price for being needed — you can fall apart later, on a schedule, maybe in spring.",
            fb: "You're not a crisis line, and pretending to be one has a known ending: you burn out, start resenting them, and eventually vanish — which is worse for your friend than any boundary would have been. Unsustainable support isn't kindness; it's a loan the friendship can't repay." },
          { kind: "avoid", backbone: 0, traits: { S: -1, A: -2 },
            text: "Start letting the calls ring out. No explanation — you'll 'catch up when things calm down.' They'll figure it out.",
            fb: "Ghosting a drowning person teaches them the worst possible lesson — that reaching out costs them relationships. The boundary you were too tired to say out loud still got delivered, just in the cruelest available packaging." },
          { kind: "good", backbone: 1, traits: { S: 2, A: 2 },
            text: "Say the caring boundary in daylight: \"I'm completely in your corner and I want to keep being — which is why I can't do 2am calls on work nights. Call me at 8 any evening and you have my full attention. If it's 2am-bad, that's what the crisis line is for, genuinely — they're better at 2am than I am.\"",
            fb: "Boundary and devotion in the same breath — the formula for support that survives. 'I can't do X, here's the generous Y I can do' keeps you in their corner for the months this will actually take, and routing true 2am crises to people trained for them is care, not abandonment." },
          { kind: "good", backbone: 0, traits: { S: 2, C: 1 },
            text: "Give the support a shape: a standing evening walk three times a week, on the calendar — plus a gentle truth: \"I'm better company as a scheduled friend than a depleted one.\"",
            fb: "Structure protects both of you: they get reliable, guaranteed support (often more total minutes than the chaos version), and you get to recharge enough to keep providing it. Predictable care beats heroic care over any distance longer than a sprint." },
        ] },
    ] },
  { id: "defining", emoji: "🌊", title: "Getting Real",
    desc: "The define-the-relationship zone: exactly where doormats get made.",
    scenarios: [
      { id: "rl-dtr", tag: "The talk", focus: "E",
        text: "Three months in. It's wonderful. It's also… undefined. You want exclusivity; the apps are still on their phone. Every time the topic nears, your throat closes and you change the subject.",
        choices: [
          { kind: "avoid", backbone: -1, traits: { S: -2, E: -1 },
            text: "Keep waiting for them to raise it. Drop hints. Analyze their emoji usage for signals. Month five, same throat, same silence.",
            fb: "The unasked question is answered every day by default — and the default is their preference, not yours. Hint-dropping is asking without the courage part, and it reads as exactly that." },
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "Decide wanting labels is 'a lot' and needy. Retrofit your preferences to match whatever this is. Practice looking breezy.",
            fb: "You didn't lower the stakes — you abandoned your position and called it chill. 'Cool with anything' is the doormat's native language, and it attracts people who benefit from it." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, S: 2 },
            text: "Over dinner, plainly: \"I've stopped wanting to see anyone else — I want us exclusive. How do you feel?\" Then the hard part: silence. Let them answer.",
            fb: "One declarative sentence, one open question, zero hedging — and letting the silence sit instead of nervously backfilling it. Whatever the answer, you just saved months." },
          { kind: "assertDiplo", backbone: 1, traits: { E: 1, A: 1, S: 1 },
            text: "\"Three months in and you're still my favorite plans. Where's your head at with us? I'll go first if you want — I know what I'd pick.\"",
            fb: "Warm on-ramp, real question, and 'I'll go first' signals courage while offering them a turn. The vulnerability is the point — it's also the screen: watch what they do with it." },
        ] },
      { id: "rl-pace", tag: "Pace", focus: "A",
        text: "They want you to meet their entire family at a reunion next month. You're happy, but this is fast for you, and your gut says 'not yet.' They look so excited.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "\"Sounds great!\" Book the flights. Spend a month low-grade dreading it. Arrive as a slightly haunted version of yourself.",
            fb: "Overriding your gut to protect their excitement means the family meets an anxious performance, not a partner. A yes that costs a month of dread was never really a yes." },
          { kind: "aggressive", backbone: 0, traits: { A: -2 },
            text: "\"Whoa. A family reunion? That's a LOT. Why are you rushing this?\"",
            fb: "'Why are you rushing' converts their happy invitation into an accusation and puts them on trial for enthusiasm. The pace concern is fair; the prosecution isn't." },
          { kind: "assertDirect", backbone: 1, traits: { A: 1, S: 2 },
            text: "\"I love that you want me there — genuinely. A full reunion is ahead of my pace. Can we start with dinner with your sister first? I want the family thing to happen — a step later than this.\"",
            fb: "Feeling honored and declining the timeline can coexist — you proved it in three sentences, with a concrete counter-step so 'not yet' visibly isn't 'not ever'." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 2, S: 1 },
            text: "\"Tell me about everyone first — who's the one I have to win over, who corners people about politics? …Okay. I want in eventually, but a 40-person debut is my nightmare. Build me up to it?\"",
            fb: "Curiosity first (which honors the invitation), then the honest limit, then delegating the on-ramp to them — they get to be your guide instead of your rejected host." },
        ] },
      { id: "rl-their-friends", tag: "Their people", focus: "E",
        text: "First hangout with their friend group: seven people, a decade of inside jokes, a bar too loud to think in. Your partner keeps getting pulled away. You know no one.",
        choices: [
          { kind: "avoid", backbone: 0, traits: { E: -2, S: -1 },
            text: "Attach to your partner like a barnacle, contribute smiles, count minutes, and on the ride home say 'they're great!' while feeling like you failed an exam.",
            fb: "Barnacle mode reads as disinterest to the very people trying to get a read on you. They don't need you to be dazzling — they need one real conversation to report back on." },
          { kind: "ok", backbone: 0, traits: { E: 1 },
            text: "Survive on logistics: fetch drinks, hold coats, ask where the bathroom is. Helpful, present, and completely unknowable.",
            fb: "Useful is a supporting role. The friends' verdict — and there will be one — needs material: one opinion, one story, one question of yours to quote back to your partner." },
          { kind: "good", backbone: 0, traits: { E: 2, S: 1 },
            text: "Pick ONE friend — the one your partner mentions most — and go deep instead of wide: \"You're the Priya of the stories, right? The rooftop incident — I need the real version.\"",
            fb: "Knowing the lore is instant belonging, and one genuine ally beats seven polite exchanges: the group's verdict is written by whoever talked to you longest." },
          { kind: "good", backbone: 0, traits: { E: 2, A: 1 },
            text: "Give the group a gift: \"Okay, settle something — [partner] claims the group agrees pineapple pizza is elite. I need a ruling.\" Let the ancient argument do the bonding.",
            fb: "Handing a group their favorite argument is social jiu-jitsu — you're instantly inside the dynamic instead of observing it, and the noise does the work your nerves can't." },
        ] },
    ] },
  { id: "conflict", emoji: "⛈️", title: "Conflict & Repair",
    desc: "Every couple fights. The good ones fight well and repair fast.",
    scenarios: [
      { id: "rl-first-fight", tag: "The fight", focus: "S",
        text: "Your first real fight — it started about the dishes and is now, somehow, about respect. Voices are up. They just said something that genuinely stung, and your reply is loaded and aimed.",
        choices: [
          { kind: "aggressive", backbone: 0, traits: { A: -3, S: -2 },
            text: "Fire it. The one about their mother. It's devastating because it's accurate, and right now devastating feels like winning.",
            fb: "Fights end; sentences don't. The precision-guided insult wins the exchange and salts the field — some things said at volume take years to un-hear." },
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "Fold completely: \"you're right, it's all my fault, I'm the worst, forget I said anything.\" Anything to make the loudness stop.",
            fb: "That's not peace, it's surrender-as-anesthesia — the issue survives, now with a precedent that escalation makes you fold. Fake harmony is just conflict on layaway." },
          { kind: "good", backbone: 1, traits: { S: 3, A: 1 },
            text: "Put both hands up, literally: \"I'm too hot to be fair right now and I don't want to say something I'll mean for ten seconds and regret for a year. Twenty minutes, then I'm coming back to finish this — because it matters.\"",
            fb: "The timeout-with-a-return-time is the single most evidence-backed move in couples research — it stops the flooding without becoming stonewalling. 'I'm coming back' is the load-bearing clause." },
          { kind: "good", backbone: 0, traits: { S: 2, A: 2 },
            text: "Drop the score sheet mid-air: \"Wait. I think we're both defending instead of listening. Say the dishes thing again — I'll actually hear it this time.\"",
            fb: "Someone has to be the first to stop winning — it's the highest-leverage sentence in any fight. Repair attempts mid-conflict are the #1 predictor of couples that last." },
        ] },
      { id: "rl-chores", tag: "The ledger", focus: "A",
        text: "You've noticed you do roughly all of the invisible work: appointments, groceries, remembering their mother's birthday. Tonight, watching them relax while you meal-plan, the resentment is physically warm.",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -3 },
            text: "Say nothing, again. Keep score silently, again. Let the resentment compound into that special vintage that eventually gets served all at once.",
            fb: "Unspoken ledgers always get paid — usually in one catastrophic invoice during an unrelated argument. Resentment is anger you chose not to say, charging interest." },
          { kind: "aggressive", backbone: 0, traits: { A: -2 },
            text: "\"Must be nice. Do you even know when your OWN dentist appointment is? Because I do. I know everything, apparently, for both of us.\"",
            fb: "Sarcasm delivers the grievance pre-wrapped in contempt — the one ingredient couples researchers call the relationship killer. The complaint is fair; the packaging is poison." },
          { kind: "assertDirect", backbone: 1, traits: { A: 1, S: 1, C: 1 },
            text: "Not mid-annoyance — Saturday coffee: \"I'm carrying most of the invisible work — here's the actual list. It's making me resentful and I don't want that. Which of these do you fully own from now on?\"",
            fb: "The written list defeats the 'I do lots!' vagueness, the timing defeats the defensiveness, and 'fully own' defeats the helper trap — where they assist and you still manage everything." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 2, S: 1 },
            text: "\"Can we play a game? Both of us list everything we think we each handle. Compare lists.\" (The gap in the lists makes the argument for you.)",
            fb: "Letting them discover the imbalance beats announcing it — self-generated realizations don't trigger the defenses that accusations do. The lists do the confronting; you just brought paper." },
        ] },
      { id: "rl-jealousy", tag: "The spiral", focus: "S",
        text: "You saw a text preview light up: a coworker's name, a heart emoji, 'can't wait!!'. Your partner laughed at something on their phone twice tonight. The story writing itself in your head has plot, motive, and a season two.",
        choices: [
          { kind: "avoid", backbone: 0, traits: { S: -3, A: -1 },
            text: "Say nothing; investigate. Check their phone when they shower. Cross-reference the coworker's socials. Become, quietly, a private detective with a stomach ache.",
            fb: "Surveillance treats your anxiety by violating their privacy — it finds either nothing (no relief, repeat next week) or ambiguity (more fuel). The spiral cannot be investigated closed, only asked closed." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "\"Who's making you laugh like that? Show me the phone if it's so innocent. The HEART emoji, really?\"",
            fb: "The prosecution opening guarantees a defensive response — which your spiral will read as guilt, even when it's just the normal human response to being ambushed. You've made honesty expensive." },
          { kind: "good", backbone: 1, traits: { S: 3, A: 1 },
            text: "Name the feeling, not the accusation: \"Weird honest moment — I saw a text preview earlier and my brain's been writing fanfiction since. I don't actually think anything's wrong. Can you talk me down?\"",
            fb: "Vulnerability outperforms interrogation everywhere it's tried: you handed them the chance to reassure instead of defend, and 'my brain's writing fiction' names the spiral as yours to co-manage." },
          { kind: "good", backbone: 0, traits: { S: 2 },
            text: "Audit the spiral first: the 'evidence' is a heart emoji (they send those to everyone) and laughter (a crime?). Recognize mind-reading + mental filter. If unease persists tomorrow, ask calmly then.",
            fb: "Running the distortion check before the conversation means whatever you say comes from the calm 20% of you instead of the theatrical 80%. Half the time the case dissolves on review." },
        ] },
    ] },
  { id: "worlds", emoji: "🌍", title: "Worlds Collide",
    desc: "In-laws, friends, and holidays: defending the relationship from the outside.",
    scenarios: [
      { id: "rl-inlaw", tag: "In-laws", focus: "A",
        text: "Your partner's mother, at her own dinner table, fourth visit running: \"Of course, [ex's name] always made the roast from scratch. Store-bought is fine too, I suppose, for busy people.\"",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -2 },
            text: "Smile until your face aches. Compliment her roast. Spend the drive home dissecting the ex comment for the fourth consecutive visit.",
            fb: "Four visits of absorbing it has established the sport, and she's not going to retire undefeated on her own. The drive-home autopsy is the cost of the dinner-table silence." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "\"You know, it's fascinating how [ex] comes up more often at this table than at our actual breakup.\"",
            fb: "A direct hit on her own turf, in front of the family — you won the exchange and handed her the victim role plus witnesses. In-law wars have no winners, only longer holidays." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 2, S: 2 },
            text: "Bright, unbothered, fog it: \"From scratch is impressive! I've made peace with my bakery loyalty.\" Then, privately, the real conversation — with your partner: \"The ex comparisons need to end. I need you to handle your mother.\"",
            fb: "Two-front mastery: in public, fogging denies her the flinch she's fishing for; in private, the boundary goes to the only person with jurisdiction — your partner. In-law rule one: your partner manages their parent." },
          { kind: "assertDirect", backbone: 1, traits: { S: 2 },
            text: "Level, warm, once: \"You mention her a lot when I'm here. I'd love us to get to know each other as we actually are — I'm not competing with anyone.\" Then pass the potatoes like nothing happened.",
            fb: "Naming the pattern gently, to her face, with an olive branch attached — high-risk, high-respect. Some matriarchs escalate; most, when named calmly, retire the material forever." },
        ] },
      { id: "rl-friend-hate", tag: "Friends", focus: "S",
        text: "Your best friend, three drinks in: \"Honestly? I don't get it. You've been different since you two got together. Duller. The old you would agree with me.\"",
        choices: [
          { kind: "avoid", backbone: 0, traits: { S: -2 },
            text: "Laugh it off, change the subject, then quietly start seeing the friend less AND second-guessing the relationship. Feed both anxieties, resolve neither.",
            fb: "The unexamined accusation now lives rent-free in two rooms of your life. It deserved either a real conversation or a real dismissal — the half-dodge delivers the costs of both." },
          { kind: "aggressive", backbone: 0, traits: { A: -2 },
            text: "\"Duller? You mean I stopped closing bars with you every weekend. You're not missing ME, you're missing your wingman.\"",
            fb: "Possibly true! And now unfindable under the rubble, because diagnosis-as-warfare ends conversations rather than opening them. Three drinks in was also not the venue." },
          { kind: "good", backbone: 1, traits: { S: 2, A: 1 },
            text: "Take it seriously, sober, later: \"You said something that stuck. What do you actually miss? If I've genuinely dropped the friendship, I want to fix that. If this is about not liking them — say that instead, and make your case.\"",
            fb: "You split the two possible truths — neglected friend vs. hostile friend — and demanded whichever is real be argued properly. Both deserve daylight; neither deserves a bar-stool ambush." },
          { kind: "good", backbone: 0, traits: { S: 2 },
            text: "Before reacting at all, audit it honestly: pull up the calendar. When DID you last make real time for them? If the answer stings, the fix is a standing plan, not a defense.",
            fb: "The strongest response to criticism is occasionally 'checking whether it's true' — new relationships genuinely do eat friendships, and a standing monthly plan repairs more than any rebuttal." },
        ] },
      { id: "rl-holidays", tag: "Holidays", focus: "A",
        text: "December. Your family expects you both, five hours north. Their family expects you both, three hours south. Both mothers have used the phrase 'it would break my heart.' Your partner says 'you decide, I'm easy.'",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -3, C: -1 },
            text: "Attempt both: 10 hours of driving, two half-visits, everyone slightly disappointed, you and your partner arriving home Dec 26 like survivors of something.",
            fb: "The both-mothers special: you optimized for zero short-term guilt and purchased it with the actual holiday. Everyone got a fraction of you; the relationship got the leftovers." },
          { kind: "avoid", backbone: 0, traits: { S: -2 },
            text: "Stall until Dec 18, when the decision makes itself via train prices, and both families learn they were runner-up by default.",
            fb: "Deciding by not deciding delivers all the disappointment with none of the credit for choosing. Families forgive a clear plan; they remember a shrug." },
          { kind: "assertDirect", backbone: 1, traits: { S: 2, C: 1, A: 1 },
            text: "First, refuse the hospital pass: \"You're not 'easy,' you're avoiding the heat — decide WITH me.\" Then together: alternate years, announced in October, same rule forever: \"This year north, next year south. It's the system now.\"",
            fb: "Two boundaries in one: your partner doesn't get to outsource the guilt-management, and the mothers get a system instead of an annual competition. Systems can't have their feelings hurt." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 2, S: 1 },
            text: "Give each mother a consolation prize with a date on it: \"We're south for the 25th this year — AND we're booking the first weekend of January with you, just us, no competing with twelve cousins for the good chair.\"",
            fb: "The dedicated January visit is often genuinely better than the shared-custody Christmas — you've converted 'runner-up' into 'exclusive engagement,' which is the rare boundary that arrives as an upgrade." },
        ] },
    ] },
  { id: "longhaul", emoji: "🛶", title: "The Long Haul",
    desc: "Money, space, and big decisions — partnership as a practice.",
    scenarios: [
      { id: "rl-money", tag: "Money", focus: "C",
        text: "Moving in together made it visible: you're a saver with a spreadsheet; they consider a budget 'a vibe.' The third surprise purchase this month just arrived in a very large box.",
        choices: [
          { kind: "avoid", backbone: -1, traits: { S: -2, C: -1 },
            text: "Say nothing and silently compensate — save double, skip your own wants, keep a private resentment ledger alongside the actual ledger.",
            fb: "You've become the unpaid CFO of a company that doesn't know it has one. Silent compensation feels noble and reads as approval — the boxes will keep coming." },
          { kind: "aggressive", backbone: 0, traits: { A: -2 },
            text: "\"ANOTHER box? Do you understand how money works? I'm not saving for two while you cosplay as someone with a trust fund.\"",
            fb: "Money shame is the fastest way to convert a spender into a secret spender — the purchases continue, underground, plus now there's lying. Contempt never balanced a budget." },
          { kind: "assertDirect", backbone: 1, traits: { C: 2, A: 1, S: 1 },
            text: "Schedule it, don't ambush it: \"Money date, Sunday, pastries provided. Three numbers: joint costs, joint savings, and — this part matters — guilt-free personal money for each of us. Yours is yours, no commentary from me ever.\"",
            fb: "The guilt-free allowance is the peace treaty that works: your security gets its system, their spontaneity gets a protected habitat, and nobody audits anybody's large boxes again." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 1, C: 1, S: 1 },
            text: "Lead with curiosity, not the spreadsheet: \"What did money mean growing up in your house? …Here's what it meant in mine — which is why surprise boxes make my chest tight. Can we design something that fits us both?\"",
            fb: "Money fights are rarely about math — they're two childhoods arguing. Surfacing the origin stories first turns 'your habits are wrong' into 'our systems differ,' which is solvable." },
        ] },
      { id: "rl-space", tag: "Space", focus: "S",
        text: "You love them. You also haven't been alone — truly alone — in six weeks, and you can feel yourself getting irritable at things that aren't crimes, like how they breathe near you while you read.",
        choices: [
          { kind: "avoid", backbone: -1, traits: { S: -2 },
            text: "Suppress it — needing space must mean something's wrong with the relationship, so bury the need and let the irritability leak out sideways as snippiness about dishes.",
            fb: "The need for solitude is a trait, not a symptom — but denied traits don't vanish, they ferment. The dish-snippiness IS the space request, translated into its worst possible language." },
          { kind: "ok", backbone: 0, traits: { S: 0 },
            text: "Engineer stealth solitude: invent errands, take the long way home, develop a sudden passion for very long grocery runs.",
            fb: "It works, briefly — but stealth space requires lying logistics and teaches them nothing about how you're built. You're meeting a legitimate need through a side door." },
          { kind: "good", backbone: 1, traits: { S: 2, A: 1 },
            text: "Say the scary sentence with its full context: \"I need a solo evening a week — it's how I recharge, it's how I was before we met, and it's the opposite of a problem with us. Tuesdays? You get the same, obviously.\"",
            fb: "Framing solitude as maintenance rather than distance — and offering it reciprocally — converts the scariest ask into the most ordinary one. Secure partners hear 'Tuesdays' with relief, not alarm." },
          { kind: "good", backbone: 0, traits: { S: 2, O: 1 },
            text: "Check the story you're telling first: does needing space mean the relationship is failing — or is that all-or-nothing thinking? (Every thriving couple you actually admire has separate hobbies. Evidence noted.) Then ask for the Tuesday.",
            fb: "You caught the distortion — 'togetherness or trouble' is a false binary the anxious brain sells hard. The audit made the ask possible; the ask makes the relationship durable." },
        ] },
      { id: "rl-big-decision", tag: "The fork", focus: "E",
        text: "They just got a real offer: dream role, another city, answer due in two weeks. They're glowing and terrified. \"I won't take it if you don't want to move. Seriously. Just say the word and it's gone.\"",
        choices: [
          { kind: "doormat", backbone: -1, traits: { S: -3 },
            text: "\"Whatever makes you happy!\" — abdicating entirely, privately packing dread, keeping your career and your terror politely off the table.",
            fb: "'Whatever you want' at a life fork isn't generosity — it's absence. You've exiled yourself from a decision that owns half your future, and resentment loves a decision it wasn't part of." },
          { kind: "aggressive", backbone: 0, traits: { A: -2, S: -1 },
            text: "\"So your dream job outranks my entire life here? Good to know where I rank. Take it, then. Clearly you already decided.\"",
            fb: "They offered you a veto and you returned an ultimatum — the fastest way to guarantee whichever choice happens, it happens with a wound in it. Fear is running your mouth." },
          { kind: "assertDirect", backbone: 1, traits: { E: 2, S: 2 },
            text: "Refuse the veto, join the decision: \"I won't be the person who killed your dream job, and I won't pretend I have no stakes. Two weeks: we list what I'd need for the move to work FOR ME — remote terms, a one-year review point, flights home budgeted. Then we decide together.\"",
            fb: "Neither martyr nor hostage: you converted a binary loaded with future resentment into a design problem with conditions. 'What I'd need for this to work for me' is the adult sentence of the decade." },
          { kind: "assertDiplo", backbone: 1, traits: { A: 1, E: 1, O: 1 },
            text: "\"Before any verdicts — 48 hours where we're both allowed to want things out loud. Tonight you pitch me the city like a travel agent. Tomorrow I tell you everything I'm scared to lose. THEN we negotiate like people on the same team.\"",
            fb: "Structuring the conversation before having it — desires first, fears second, decisions last — prevents the premature compromise where both people concede things nobody asked them to. Same team is a practice, not a slogan." },
        ] },
    ] },
];
